function initAdaptiveBreadcrumbs(){document.querySelectorAll(".breadcrumbs").forEach(d=>{const r=d.querySelector(".breadcrumbs__list");if(!r)return;let t=r.querySelector(".breadcrumbs__dots-item");t||(t=document.createElement("li"),t.className="breadcrumbs__item breadcrumbs__dots-item",t.innerHTML='<span class="breadcrumbs__dots" aria-hidden="true"></span>',r.insertBefore(t,r.children[1]));const n=()=>{const s=Array.from(r.children);if(window.innerWidth>1260){s.forEach(e=>e.style.display="flex"),t.style.display="none";return}s.forEach(e=>e.style.display="flex"),t.style.display="none";const i=r.offsetWidth;if(s.reduce((e,c)=>e+c.offsetWidth,0)<=i)return;const o=s[0],a=s[s.length-1];s.forEach(e=>{e!==o&&e!==a&&e!==t&&(e.style.display="none")}),t.style.display="flex"};n(),window.addEventListener("resize",n)})}document.addEventListener("DOMContentLoaded",()=>{initAdaptiveBreadcrumbs()});
